INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gull-stand', 'north', 'the-high-water-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-beds', 'north', 'the-storm-ridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-water-mark', 'door', 'The High-Water Mark', 'A line of wrack lies along the top of the shoal — weed, cork, feathers, a broken oar, everything the biggest tides bring up and leave — and it marks where the sea stops. Above it the ground is grey-green and firm and stays out of the water. Behind you, the gulls and the ford. Ahead, the saltings, and nobody''s footprints in them.', 0, 0, 'crossing', 0, 55, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-water-mark', 'south', 'the-gull-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-water-mark', 'north', 'the-sea-lavender', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salt-workings', 'door', 'The Salt Workings', 'Shallow square pans dug into the clay of the marsh and banked round, a long time ago, to let the sea in and the sun take it out again. The banks are still there, grassed over, the floors white-crusted where the water stands. Somebody worked salt here for a living. The ground between the pans is flat and firm and dry.', 0, 0, 'crossing', 0, 52, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-workings', 'north', 'the-grey-marsh', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sea-purslane', 'door', 'The Sea Purslane', 'Grey-silver bushes of purslane, knee-high, crowding the banks of a creek so that the creek itself is a dark line you only see when you are on the edge of it. The mud below is soft and very deep.', 0, 0, 'crossing', 0, 53, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-purslane', 'east', 'the-crooked-creek', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-purslane', 'north', 'the-cord-grass', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crooked-creek', 'door', 'The Crooked Creek', 'A creek winds through the marsh here in loops so tight that you can cross it three times in twenty paces and never get further from where you started. The banks are mud, glossy and steep, printed with birds'' feet.', 0, 0, 'crossing', 0, 54, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crooked-creek', 'north', 'the-saltmarsh-pools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crooked-creek', 'west', 'the-sea-purslane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sea-lavender', 'door', 'The Sea Lavender', 'Sea lavender over the whole marsh top here, a haze of it, low and purple-grey, smelling faintly of nothing at all. Under it the ground is firm and cut with little runnels that go nowhere.', 0, 0, 'crossing', 0, 55, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-lavender', 'south', 'the-high-water-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-lavender', 'east', 'the-samphire-flats', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-samphire-flats', 'door', 'The Samphire Flats', 'Samphire, bright green and fleshy, standing in the open mud between the creeks in little upright stems like a crop somebody planted. It squeaks underfoot. Pull it and it comes up whole.', 0, 0, 'crossing', 0, 56, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-flats', 'west', 'the-sea-lavender', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-flats', 'east', 'the-storm-ridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-storm-ridge', 'door', 'The Storm Ridge', 'A long ridge of shingle thrown up above the cockle beds by some winter that nobody remembers, steep on the seaward side and gentle on the other. Stand on the crest and the crossing is laid out below you, all its water and all its ways. Turn round and there is the marsh, and the dunes beyond it, and no way through either that you can see from here.', 0, 0, 'crossing', 0, 57, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-storm-ridge', 'south', 'the-cockle-beds', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-storm-ridge', 'west', 'the-samphire-flats', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-storm-ridge', 'east', 'the-wide-creek', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wide-creek', 'door', 'The Wide Creek', 'A creek too wide to jump, with no way across it you can see, running full of brown water at one hour and empty to a gutter of mud at the next. Going round it means following it, and it goes a long way.', 0, 0, 'crossing', 0, 58, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wide-creek', 'west', 'the-storm-ridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wide-creek', 'north', 'the-old-sea-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-marsh', 'door', 'The Grey Marsh', 'Flat marsh to the edge of sight in every direction, grey-green, cut by creeks, all at exactly the same height. There is nothing to steer by. Every creek looks like the last one.', 0, 0, 'crossing', 0, 52, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-marsh', 'east', 'the-cord-grass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-marsh', 'north', 'the-white-dunes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-marsh', 'south', 'the-salt-workings', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cord-grass', 'door', 'The Cord Grass', 'Cord grass, stiff and green, grown in a dense band along a creek bank, taller than your waist. It holds the mud together and the mud holds you, mostly. Walk the top of the bank, not the side of it.', 0, 0, 'crossing', 0, 53, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cord-grass', 'south', 'the-sea-purslane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cord-grass', 'west', 'the-grey-marsh', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-saltmarsh-pools', 'door', 'The Saltmarsh Pools', 'Round pools lie in the marsh top here, each one still and full of sky, edged with short turf. There are dozens of them. The way between them is a thread of firm ground that bends where the pools do.', 0, 0, 'crossing', 0, 54, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmarsh-pools', 'north', 'the-marram-sea', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmarsh-pools', 'east', 'the-redshank-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmarsh-pools', 'south', 'the-crooked-creek', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-redshank-ground', 'door', 'The Redshank Ground', 'A bird gets up from the marsh in front of you and goes off piping, and another, and another, all of them shouting the same alarm, and then the whole marsh knows you are here. They settle again behind you. They do not stop watching.', 0, 0, 'crossing', 0, 55, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-redshank-ground', 'west', 'the-saltmarsh-pools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-redshank-ground', 'east', 'the-drained-creek', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drained-creek', 'door', 'The Drained Creek', 'A creek emptied by the falling tide, its bed a channel of shining mud with a trickle down the middle, its banks slumped and fissured. Things have walked along the bottom of it. Their prints go both ways.', 0, 0, 'crossing', 0, 56, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drained-creek', 'west', 'the-redshank-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drained-creek', 'east', 'the-samphire-island', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-samphire-island', 'door', 'The Samphire Island', 'A low island of firm ground stands up out of the creeks here, ringed all round by water at every tide but the lowest, grassed on top and dry. The creeks go past it on both sides and meet again beyond. From the middle of it the marsh is flat to the edge of sight, and anything coming across it can be seen a long way off.', 0, 0, 'crossing', 0, 57, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-island', 'west', 'the-drained-creek', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-sea-bank', 'door', 'The Old Sea Bank', 'A bank of earth, grassed over, runs straight across the marsh here — built by hand to keep the sea off land that the sea took anyway. It is the only straight thing for miles and it stops suddenly in both directions.', 0, 0, 'crossing', 0, 58, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-sea-bank', 'south', 'the-wide-creek', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-sea-bank', 'north', 'the-grey-dunes', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-white-dunes', 'door', 'The White Dunes', 'Dunes, high and pale and loose, the sand moving on their crests in thin streams with every gust. They have no shape that stays. Climbing one, the sand runs out from under every step and you go up half as fast as you meant to.', 0, 0, 'crossing', 0, 52, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-dunes', 'south', 'the-grey-marsh', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-dunes', 'east', 'the-dune-slack', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dune-slack', 'door', 'The Dune Slack', 'A hollow between the dunes floored with short wet turf, where fresh water stands in the low places after rain and the wind goes over the top without coming down. Orchids grow in it, and creeping willow no higher than your ankle. It is the one green, sheltered, sweet-watered place in all this sand, and it is a long way from anywhere.', 0, 0, 'crossing', 0, 53, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dune-slack', 'west', 'the-white-dunes', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-marram-sea', 'door', 'The Marram Sea', 'Marram grass over every dune in sight, tall and stiff and blue-grey, bending all one way and hissing. Walk into it and it closes behind you to the shoulder. Every dune looks the same from inside it.', 0, 0, 'crossing', 0, 54, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marram-sea', 'east', 'the-blowout', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marram-sea', 'south', 'the-saltmarsh-pools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-blowout', 'door', 'The Blowout', 'The wind has torn a dune open here, a bare bowl of sand scooped out of its side with the roots of the marram hanging in the air round the rim. The floor of it is ridged like a beach. The wind is still working on it.', 0, 0, 'crossing', 0, 55, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blowout', 'east', 'the-dune-ridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blowout', 'west', 'the-marram-sea', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dune-ridge', 'door', 'The Dune Ridge', 'A long ridge of dune, crested with marram, from which you can see the sea on one side and more dunes on the other, rank on rank, all the same height. The sand on the crest is warm. The sand in the hollows is cold.', 0, 0, 'crossing', 0, 56, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dune-ridge', 'east', 'the-sea-buckthorn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dune-ridge', 'west', 'the-blowout', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sea-buckthorn', 'door', 'The Sea Buckthorn', 'Sea buckthorn, grey-leaved and orange-berried, grown into a thicket across a dune hollow, every branch armed with thorns as long as a finger. There is a way through, made by something low.', 0, 0, 'crossing', 0, 57, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-buckthorn', 'east', 'the-grey-dunes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-buckthorn', 'west', 'the-dune-ridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-dunes', 'door', 'The Grey Dunes', 'Older dunes, further from the sea, grown over with grey lichen and moss and low heath, so the sand is held still under a crust. They roll away in every direction like a sea frozen at the moment of a swell.', 0, 0, 'crossing', 0, 58, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-dunes', 'south', 'the-old-sea-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-dunes', 'west', 'the-sea-buckthorn', NULL);
